import numpy as np
T = 1_000_000_000_000                  # 총 1T 토큰
decay_frac = 0.1                       # 마지막 10% 가 감쇠(중간학습) 단계
stable = {"web": 0.74, "code": 0.25, "math": 0.01}
decay = {"web": 0.45, "code": 0.20, "math": 0.05, "wiki/books": 0.10, "SFT/chat": 0.20}
tot = {}
for mix, frac in [(stable, 1 - decay_frac), (decay, decay_frac)]:
    for k, v in mix.items():
        tot[k] = tot.get(k, 0) + v * frac * T
for k, v in tot.items():
    print(f"{k:10s} {v/1e9:7.0f}B 토큰  ({v/T:.1%})")
# WSD 학습률: 워밍업 1%, 유지, 마지막 10% 선형 감쇠
def lr(t, peak=3e-4, warm=0.01, d=0.1):
    if t < warm: return peak * t / warm
    if t < 1 - d: return peak
    return peak * (1 - t) / d
print([f"{lr(x):.1e}" for x in (0.005, 0.5, 0.9, 0.95, 0.999)])
